def transform(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    # diagonal-colored cells (non-background, non-bar): identify background and bar
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    cells=Counter()
    for row in g:
        for x in row:
            if x!=bg: cells[x]+=1
    # bar = most frequent non-bg, diagonal = other
    order=[c for c,_ in cnt.most_common() if c!=bg]
    bar,diag=order[0],order[1]
    diag_cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==diag]
    hit=set()
    for c in range(W):
        for r0 in range(H):
            if g[r0][c]!=bar: continue
            for d in (-1,1):
                r=r0+d
                while 0<=r<H:
                    if g[r][c]==diag:
                        hit.add((r,c)); break
                    if g[r][c]!=bg: break
                    r+=d
    for (r,c) in hit:
        r0=r
        # determine which side(s) to fill: fill between bar and diag cell
        for d in (-1,1):
            r=r0+d
            while 0<=r<H and g[r][c]==bg:
                out[r][c]=diag; r+=d
    for (r,c) in hit:
        out[r][c]=4
    return out

